PIPE = '#!/bin/bash\n# Rebuild Strata (v5: relay hanya kalau agent.py ada). Sandbox tanpa snapshot.\nset -uo pipefail\nmkdir -p /marimo/llm\ncd /marimo/llm\nLOG=/marimo/llm/pipeline.log\nKEY=sk-strata-d71951f458683d6a913c18fb1e31e4b3\nMODEL=/home/marimo/models/sc117\nsay(){ echo "[$(date -u +%T)] $*" >> "$LOG"; }\nphase(){ echo "$1" > /marimo/llm/phase; say "fase: $1"; }\n\nmkdir -p "$MODEL/IQ3_S" /marimo/llm/sc117-aux /marimo/llm/sc117-data/mtp\necho "$KEY" > /marimo/llm/api_key.txt\nsay "===== mulai ====="\nphase start\n\npkill -f "[s]tatus_loop.py" 2>/dev/null\nnohup python3 /marimo/llm/status_loop.py > /marimo/llm/status.log 2>&1 &\n\nphase strata\n(\n  curl -fsSL https://github.com/Niko1221/Strata/releases/latest/download/install.sh -o /tmp/si.sh\n  env -u PYTHONPATH -u PYTHONSAFEPATH -u VIRTUAL_ENV -u PYTHONHOME \\\n      PATH=/usr/local/bin:/usr/bin:/bin:/usr/local/sbin:/usr/sbin:/sbin \\\n      sh /tmp/si.sh\n  python3 -c "import websockets" 2>/dev/null || python3 -m pip install --quiet websockets\n) >> "$LOG" 2>&1 &\nSTRATA=$!\n\nR=SC117/Qwen3.8-Flash-Next-GSQ-RCO-abliterated-GGUF\nphase download\n( hf download "$R" --include "strata/rt/*" --local-dir /marimo/llm/sc117-aux \\\n    && hf download "$R" mmproj-Qwen3.8-Flash-Next-BF16.gguf --local-dir "$MODEL/IQ3_S" ) \\\n    >> "$LOG" 2>&1 &\nAUX=$!\n\nhf download "$R" --include "IQ3_S/*.gguf" --local-dir "$MODEL" >> "$LOG" 2>&1\nsay "shards rc=$? $(du -sh "$MODEL" 2>/dev/null | cut -f1)"\nphase aux\nwait $AUX\nsay "aux rc=$?"\n\nwait $STRATA\nsay "strata rc=$?"\n\nphase prep\ncp -r /marimo/llm/sc117-aux/strata/rt /marimo/llm/sc117-data/mtp/ 2>/dev/null\nsay "prep ok"\n\ncat > /marimo/llm/launch.sh <<\'EOL\'\n#!/bin/bash\ncd /marimo/llm\nS=/home/marimo/.local/share/strata/terminal/current/bin/strata\nexec env -u PYTHONPATH -u PYTHONSAFEPATH -u VIRTUAL_ENV "$S" launch \\\n  --model-path /home/marimo/models/sc117/IQ3_S --model iq3_s --family swift \\\n  --data-dir /marimo/llm/sc117-data --context 256k --vision gpu --mtp on \\\n  --kv int8 --tune skip --access local --port 8081 \\\n  --api-key sk-strata-d71951f458683d6a913c18fb1e31e4b3 --yes --no-tui\nEOL\nchmod +x /marimo/llm/launch.sh\n\nphase launch\nnohup bash /marimo/llm/launch.sh >> /marimo/llm/launch.log 2>&1 &\nsay "launch pid=$!"\n\ncode=000\nfor i in $(seq 1 200); do\n  code=$(curl -s -o /dev/null -w "%{http_code}" -m 2 http://127.0.0.1:8081/v1/models -H "Authorization: Bearer $KEY")\n  [ "$code" = "200" ] && break\n  sleep 2\ndone\nsay "server=$code setelah $((i*2))s"\n\nif [ -f /marimo/llm/agent.py ]; then\n  phase relay\n  nohup bash /marimo/llm/relay.sh >> /marimo/llm/relay.log 2>&1 &\n  for i in $(seq 1 30); do\n    pub=$(curl -s -o /dev/null -w "%{http_code}" -m 5 https://ai.wanz4bigel.dpdns.org/v1/models -H "Authorization: Bearer $KEY")\n    [ "$pub" = "200" ] && break\n    sleep 2\n  done\n  say "publik=$pub setelah $((i*2))s"\nelse\n  say "agent.py belum ada, relay dilewati"\nfi\nphase done\nsay "===== SELESAI ====="\n'
CELL = 'import json\nimport pathlib\n\nimport marimo as mo\n\nrefresh = mo.ui.refresh(default_interval="2s")\n\ntry:\n    s = json.loads(pathlib.Path("/marimo/llm/status.json").read_text())\nexcept Exception:\n    s = {}\n\npct = float(s.get("pct") or 0)\nfilled = int(round(pct / 100 * 30))\nbar = "█" * filled + "░" * (30 - filled)\neta = int(s.get("eta_s") or 0)\neta_txt = f"{eta // 60}m{eta % 60:02d}s" if eta else "—"\nlive = s.get("public") == 200\nkey = pathlib.Path("/marimo/llm/api_key.txt").read_text().strip() if pathlib.Path("/marimo/llm/api_key.txt").exists() else ""\n\nmo.vstack([\n    mo.md(f"""\n# IQ3_S (SC117 abliterated) — {\'LIVE\' if live else \'sedang dibangun\'}\n\n| | |\n|---|---|\n| **Base URL** | `https://ai.wanz4bigel.dpdns.org/v1` |\n| **API key** | `{key}` |\n| **Model** | `swift-1.5-iq3_s` · 262.144 konteks · KV int8 |\n| **Fase** | **{s.get(\'phase_label\', \'—\')}** · {s.get(\'elapsed_s\', 0)} detik |\n| **Unduhan** | `{bar}` {pct:.1f}% · {s.get(\'model_gb\', 0)} / {s.get(\'total_gb\', 0)} GB · {int(s.get(\'speed_mbps\') or 0)} MB/s · ETA {eta_txt} |\n| **RAM / VRAM** | {s.get(\'ram_gb\', 0)} GB / {s.get(\'vram_gb\', 0)} GB |\n| **Server lokal / publik** | {s.get(\'server\', 0)} / {s.get(\'public\', 0)} |\n| **Diperbarui** | {s.get(\'t\', \'—\')} |\n\nModel ada di `/home/marimo/models/sc117` (disk), jadi RAM tidak dipakai untuk 79 GB.\n\nKalau sandbox mati: **Relaunch** di molab → `bash /marimo/llm/pipeline.sh`.\nDashboard ini menyegarkan sendiri tiap 2 detik.\n"""),\n    refresh,\n])\n'
LOOP = '#!/usr/bin/env python3\n"""Tulis /marimo/llm/status.json tiap 2 detik untuk dashboard marimo."""\nimport json\nimport os\nimport pathlib\nimport subprocess\nimport time\nfrom collections import deque\n\nTOTAL_BYTES = 85_570_000_000          # shard1 + shard2 + mmproj\nMODEL_DIR = "/home/marimo/models/sc117"\nOUT = "/marimo/llm/status.json"\nKEY = "sk-strata-d71951f458683d6a913c18fb1e31e4b3"\n\nLABELS = {\n    "start": "mulai",\n    "strata": "memasang Strata",\n    "download": "mengunduh model",\n    "aux": "mengunduh runtime",\n    "prep": "menyiapkan data",\n    "launch": "memuat model ke GPU",\n    "relay": "menyambung relay",\n    "done": "selesai",\n}\n\n\ndef du(path):\n    total = 0\n    for root, _dirs, files in os.walk(path):\n        for f in files:\n            try:\n                total += os.path.getsize(os.path.join(root, f))\n            except OSError:\n                pass\n    return total\n\n\ndef ram_gb():\n    info = {}\n    with open("/proc/meminfo") as fh:\n        for line in fh:\n            k, _, v = line.partition(":")\n            info[k] = int(v.split()[0])\n    return (info["MemTotal"] - info["MemAvailable"]) / 1024 / 1024\n\n\ndef vram_gb():\n    try:\n        out = subprocess.run(\n            ["nvidia-smi", "--query-gpu=memory.used", "--format=csv,noheader,nounits"],\n            capture_output=True, text=True, timeout=3).stdout.split()\n        return int(out[0]) / 1024 if out else 0.0\n    except Exception:\n        return 0.0\n\n\ndef http_code(url, timeout=2):\n    try:\n        return int(subprocess.run(\n            ["curl", "-s", "-o", "/dev/null", "-w", "%{http_code}", "-m", str(timeout),\n             url, "-H", "Authorization: Bearer " + KEY],\n            capture_output=True, text=True, timeout=timeout + 2).stdout.strip() or 0)\n    except Exception:\n        return 0\n\n\ndef read_phase():\n    try:\n        return pathlib.Path("/marimo/llm/phase").read_text().strip()\n    except OSError:\n        return "start"\n\n\ndef main():\n    start = time.time()\n    hist = deque(maxlen=60)          # (t, bytes)\n    while True:\n        try:\n            now = time.time()\n            size = du(MODEL_DIR)\n            hist.append((now, size))\n            # kecepatan = jendela 10 detik terakhir\n            while len(hist) > 2 and now - hist[0][0] > 10:\n                hist.popleft()\n            t0, b0 = hist[0]\n            speed = (size - b0) / max(now - t0, 0.001) / 1e6 if len(hist) > 1 else 0.0\n            speed = max(speed, 0.0)\n            phase = read_phase()\n            pct = min(size / TOTAL_BYTES * 100, 100.0)\n            remain = max(TOTAL_BYTES - size, 0)\n            eta = int(remain / (speed * 1e6)) if speed > 1 else 0\n            if phase in ("aux", "prep", "launch", "relay", "done"):\n                eta = 0\n            status = {\n                "t": time.strftime("%H:%M:%S", time.gmtime()),\n                "elapsed_s": int(now - start),\n                "phase": phase,\n                "phase_label": LABELS.get(phase, phase),\n                "model_gb": round(size / 1e9, 1),\n                "total_gb": round(TOTAL_BYTES / 1e9, 1),\n                "pct": round(pct, 1),\n                "speed_mbps": round(speed, 1),\n                "eta_s": eta,\n                "ram_gb": round(ram_gb(), 1),\n                "vram_gb": round(vram_gb(), 1),\n                "server": http_code("http://127.0.0.1:8081/v1/models"),\n                "public": http_code("https://ai.wanz4bigel.dpdns.org/v1/models", 5),\n            }\n            tmp = OUT + ".tmp"\n            pathlib.Path(tmp).write_text(json.dumps(status))\n            os.replace(tmp, OUT)\n        except Exception:\n            pass\n        time.sleep(2)\n\n\nif __name__ == "__main__":\n    main()\n'

import os, subprocess, time
def sh(c,t=60):
    r=subprocess.run(["bash","-c",c],capture_output=True,text=True,timeout=t)
    return (r.stdout+r.stderr).strip()
os.makedirs("/marimo/llm", exist_ok=True)
open("/marimo/llm/status_loop.py","w").write(LOOP)
open("/marimo/llm/pipeline.sh","w").write(PIPE)
os.chmod("/marimo/llm/pipeline.sh", 0o755)
print("GPU:", sh("nvidia-smi --query-gpu=name --format=csv,noheader"))
log = open("/marimo/llm/pipeline.out","ab")
p = subprocess.Popen(["bash","/marimo/llm/pipeline.sh"], stdout=log, stderr=subprocess.STDOUT,
                     stdin=subprocess.DEVNULL, start_new_session=True)
print("pipeline pid:", p.pid)
import marimo._code_mode as cm
async with cm.get_context(skip_staleness_check=True, skip_validation=True) as c:
    c.edit_cell("Hbol", code=CELL)
    c.run_cell("Hbol")
    cid = c.create_cell("""import marimo as _mo

_mo.status.toast(
    "🧪 Siap pair — rebuild jalan",
    "Snapshot kosong, jadi agent.py saya bangun ulang. Model 85 GB sedang diunduh.",
)
""", before="Hbol")
    c.run_cell(cid)
print("toast + dashboard terpasang")
time.sleep(8)
print(open("/marimo/llm/status.json").read())
